# bracket: generated by ShapeBridge (https://github.com/gazi-faysal-jubayer/shapebridge)
# Units: mm. Edit the parameters below; geometry updates from them.

import cadquery as cq
from math import sqrt


def build(width=80, depth=40, thickness=8, boss_r=12):
    boss_h = thickness * 2
    hole_r = boss_r / 2
    result = cq.Workplane("XY").box(width, depth, thickness, centered=False).translate((0, 0, 0))
    result = result.union(cq.Workplane("XY").cylinder(boss_h, boss_r, centered=(True, True, False)).translate((width / 2, depth / 2, thickness)))  # boss
    result = result.cut(cq.Workplane("XY").cylinder(thickness + boss_h, hole_r, centered=(True, True, False)).translate((width / 2, depth / 2, 0)))  # hole
    result = result.cut(cq.Workplane("XY").cylinder(thickness, thickness / 2, centered=(True, True, False)).translate((thickness * 1.5, depth / 2, 0)))  # slot_l
    result = result.cut(cq.Workplane("XY").cylinder(thickness, thickness / 2, centered=(True, True, False)).translate((width - thickness * 1.5, depth / 2, 0)))  # slot_r
    return result


result = build()
if "show_object" in globals():
    show_object(result)
else:
    cq.exporters.export(result, "bracket.step")
